import { useCallback, useMemo, useRef, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import type { BoardSize } from '../constants.ts';
import { createGame, isWon } from '../transitions.ts';
import type { GameState } from '../types.ts';
import type { GameSession } from './sessionTypes.ts';
import { readPreferences, writePreferences, type SessionPreferences } from './storage.ts';
import { useActiveClock } from './useActiveClock.ts';
import type { SessionAnnouncement } from './sessionTypes.ts';
import { useMismatchTimer } from './useMismatchTimer.ts';
import { useSessionActions } from './useSessionActions.ts';
import { freshBoardCode } from './freshBoard.ts';

function initialGame(size: BoardSize): GameState {
  const game = createGame(freshBoardCode(size));
  if (game === null) throw new Error('Could not create an initial game.');
  return game;
}

export function useGameSession(): GameSession {
  const [preferences, setPreferences] = useState<SessionPreferences>(readPreferences);
  const [state, setState] = useState<GameState>(() => initialGame(preferences.size));
  const [paused, setPaused] = useState(false);
  const [visible, setVisible] = useState(() =>
    typeof document === 'undefined' || document.visibilityState !== 'hidden',
  );
  const [revision, setRevision] = useState(0);
  const [turnNumber, setTurnNumber] = useState(0);
  const [celebration, setCelebration] = useState(false);
  const [announcement, setAnnouncement] = useState<SessionAnnouncement | null>(null);
  const [loadStatus, setLoadStatus] = useState('');
  const gameRef = useRef(state);
  const preferencesRef = useRef(preferences);
  const pausedRef = useRef(paused);
  const visibleRef = useRef(visible);
  const activeAtRef = useRef<number | null>(null);
  const generationRef = useRef(0);
  const turnNumberRef = useRef(0);
  const announcementIdRef = useRef(0);
  const refs = useMemo(() => ({
    game: gameRef,
    preferences: preferencesRef,
    paused: pausedRef,
    visible: visibleRef,
    activeAt: activeAtRef,
    generation: generationRef,
    mismatchTurn: turnNumberRef,
  }), []);
  preferencesRef.current = preferences;
  pausedRef.current = paused;
  visibleRef.current = visible;

  const clockRunning = state.started && !isWon(state) && !paused && visible;
  const flushAt = useActiveClock(refs, clockRunning, revision, setState, setVisible);
  useMismatchTimer(state.selection, clockRunning, revision, generationRef, turnNumber, turnNumberRef, gameRef, flushAt);

  const notify = useCallback((text: string): void => {
    announcementIdRef.current += 1;
    setAnnouncement({ id: announcementIdRef.current, text });
  }, []);
  const persist = useCallback((next: SessionPreferences): void => {
    preferencesRef.current = next;
    setPreferences(next);
    writePreferences(next);
  }, []);
  const setPause = useCallback((next: boolean): void => {
    pausedRef.current = next;
    setPaused(next);
  }, []);
  const commitGame = useCallback((next: GameState): void => {
    gameRef.current = next;
    setState(next);
  }, []);
  const replaceGame = useCallback((next: GameState, pauseForResume: boolean): void => {
    generationRef.current += 1;
    activeAtRef.current = null;
    commitGame(next);
    setPause(pauseForResume);
    setRevision((current) => current + 1);
    setCelebration(false);
  }, [commitGame, setPause]);
  const nextTurn = useCallback((): void => {
    turnNumberRef.current += 1;
    setTurnNumber(turnNumberRef.current);
  }, []);
  const updates = useMemo(() => ({
    flushAt,
    commitGame,
    notify,
    nextTurn,
    persist,
    replaceGame,
    setCelebration,
    setLoadStatus,
    setPause,
  }), [commitGame, flushAt, nextTurn, notify, persist, replaceGame, setPause]);
  const actions = useSessionActions(refs, updates);

  return {
    state,
    paused,
    revision,
    best: preferences.bestScores[state.board.size] ?? null,
    celebration,
    announcement,
    loadStatus,
    ...actions,
  };
}
import { useCallback, useEffect, useRef } from 'react';
import type { Dispatch, RefObject, SetStateAction } from 'react';
import { advanceGame, isWon } from '../transitions.ts';
import type { GameState } from '../types.ts';

type ClockRefs = Readonly<{
  game: RefObject<GameState>;
  paused: RefObject<boolean>;
  visible: RefObject<boolean>;
  activeAt: RefObject<number | null>;
  generation: RefObject<number>;
}>;

export function useActiveClock(
  refs: ClockRefs,
  running: boolean,
  revision: number,
  setGame: Dispatch<SetStateAction<GameState>>,
  setVisible: Dispatch<SetStateAction<boolean>>,
): (now: number) => void {
  const flushAt = useCallback((now: number): void => {
    const current = refs.game.current;
    if (!refs.visible.current || refs.paused.current || !current.started || isWon(current)) {
      refs.activeAt.current = null;
      return;
    }
    const previousTime = refs.activeAt.current;
    refs.activeAt.current = now;
    if (previousTime === null) return;
    const advanced = advanceGame(current, now - previousTime);
    if (advanced !== current) {
      refs.game.current = advanced;
      setGame(advanced);
    }
  }, [refs, setGame]);
  const flushRef = useRef(flushAt);
  flushRef.current = flushAt;

  useEffect(() => {
    if (!running) {
      refs.activeAt.current = null;
      return;
    }
    if (refs.activeAt.current === null) refs.activeAt.current = performance.now();
    const generation = refs.generation.current;
    const interval = window.setInterval(() => {
      if (generation === refs.generation.current) flushRef.current(performance.now());
    }, 50);
    return () => window.clearInterval(interval);
  }, [refs, revision, running]);

  useEffect(() => {
    const onVisibilityChange = (): void => {
      const now = performance.now();
      flushRef.current(now);
      const visible = document.visibilityState !== 'hidden';
      refs.visible.current = visible;
      setVisible(visible);
      refs.activeAt.current = visible && !refs.paused.current ? now : null;
    };
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => document.removeEventListener('visibilitychange', onVisibilityChange);
  }, [refs, setVisible]);

  useEffect(() => () => {
    refs.generation.current += 1;
  }, [refs]);

  return flushAt;
}
import { useEffect } from 'react';
import type { RefObject } from 'react';
import type { Selection } from '../types.ts';
import type { GameState } from '../types.ts';

export function useMismatchTimer(
  selection: Selection,
  running: boolean,
  revision: number,
  generationRef: RefObject<number>,
  turnNumber: number,
  turnNumberRef: RefObject<number>,
  gameRef: RefObject<GameState>,
  flushAt: (now: number) => void,
): void {
  const mismatchKey = selection.kind === 'mismatch'
    ? `${selection.first}:${selection.second}`
    : '';
  const remainingMs = selection.kind === 'mismatch' ? selection.remainingMs : 0;

  useEffect(() => {
    if (!running || mismatchKey === '') return;
    const generation = generationRef.current;
    const scheduledTurn = turnNumber;
    let timeout: number;
    const tick = (): void => {
      if (generation !== generationRef.current || scheduledTurn !== turnNumberRef.current) return;
      const current = gameRef.current;
      if (current.selection.kind !== 'mismatch') return;
      if (`${current.selection.first}:${current.selection.second}` !== mismatchKey) return;
      flushAt(performance.now());
      const updated = gameRef.current;
      if (updated.selection.kind === 'mismatch') {
        timeout = window.setTimeout(tick, Math.max(1, Math.ceil(updated.selection.remainingMs)));
      }
    };
    timeout = window.setTimeout(tick, Math.max(1, Math.ceil(remainingMs)));
    return () => window.clearTimeout(timeout);
    // Preserve the turn's original deadline as the clock renders updated remaining time.
  }, [flushAt, gameRef, generationRef, mismatchKey, revision, running, turnNumber, turnNumberRef]);
}
import { MAX_BOARD_SEED, type BoardSize } from '../constants.ts';

export function freshBoardCode(size: BoardSize, currentCode?: string): string {
  let seed: number;
  try {
    const values = new Uint32Array(1);
    window.crypto.getRandomValues(values);
    seed = ((values[0] ?? 0) % MAX_BOARD_SEED) + 1;
  } catch {
    seed = (Date.now() % MAX_BOARD_SEED) + 1;
  }
  if (`np1-${size}-${seed}` === currentCode) seed = seed === MAX_BOARD_SEED ? 1 : seed + 1;
  return `np1-${size}-${seed}`;
}

