import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react';
import type { CSSProperties, FocusEvent, KeyboardEvent } from 'react';
import type { GameState } from '../types.ts';
import { SELECTION_KIND } from '../constants.ts';
import { Card } from './Card.tsx';
import './board.css';

export type BoardHandle = Readonly<{ focusRememberedCard: () => void }>;
type BoardProps = Readonly<{
  game: GameState;
  paused: boolean;
  revision: number;
  onActivate: (index: number) => void;
}>;
type BoardStyle = CSSProperties & Readonly<{ '--card-edge': string; '--column-count': number }>;

function BoardContent({ game, paused, revision, onActivate, expose }: BoardProps & Readonly<{ expose: React.Ref<BoardHandle> }>): React.JSX.Element {
  const size = game.board.size;
  const [tabStop, setTabStop] = useState(0);
  const [cardEdge, setCardEdge] = useState(88);
  const scrollRef = useRef<HTMLDivElement>(null);
  const cards = useRef(new Map<number, HTMLButtonElement>());
  const style: BoardStyle = { '--card-edge': `${cardEdge}px`, '--column-count': size };
  const matched = useMemo(() => new Set(game.matched), [game.matched]);
  const revealed = game.selection.kind === SELECTION_KIND.ONE
    ? new Set([game.selection.index])
    : game.selection.kind === SELECTION_KIND.MISMATCH
      ? new Set([game.selection.first, game.selection.second])
      : new Set<number>();
  const blocked = paused || game.selection.kind === SELECTION_KIND.MISMATCH;

  useEffect(() => {
    setTabStop(0);
  }, [revision]);

  useEffect(() => {
    const area = scrollRef.current;
    if (area === null) return;
    const updateSize = (): void => {
      const innerWidth = Math.max(0, area.clientWidth - 12);
      const gaps = (size - 1) * 6;
      const edge = Math.max(44, Math.min(88, (innerWidth - gaps) / size));
      setCardEdge((current) => current === edge ? current : edge);
    };
    updateSize();
    const observer = new ResizeObserver(updateSize);
    observer.observe(area);
    return () => observer.disconnect();
  }, [size]);

  const rememberFocus = (event: FocusEvent<HTMLButtonElement>): void => {
    const position = Number(event.currentTarget.dataset.position);
    if (Number.isSafeInteger(position)) setTabStop(position);
    event.currentTarget.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  };

  const focusCard = (position: number): void => {
    const button = cards.current.get(position);
    if (button === undefined) return;
    setTabStop(position);
    button.focus({ preventScroll: true });
  };

  useImperativeHandle(expose, () => ({ focusRememberedCard: () => focusCard(tabStop) }), [tabStop]);

  const moveFocus = (event: KeyboardEvent<HTMLDivElement>): void => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const arrows = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'];
    if (!arrows.includes(event.key)) return;
    event.preventDefault();
    if (!(event.target instanceof HTMLButtonElement)) return;
    const current = Number(event.target.dataset.position);
    if (!Number.isSafeInteger(current)) return;
    let target = current;
    if (event.key === 'ArrowLeft' && current % size > 0) target -= 1;
    if (event.key === 'ArrowRight' && current % size < size - 1) target += 1;
    if (event.key === 'ArrowUp' && current >= size) target -= size;
    if (event.key === 'ArrowDown' && current < size * (size - 1)) target += size;
    if (target !== current) focusCard(target);
  };

  return (
    <div className="board-scroll" ref={scrollRef} onKeyDown={moveFocus}>
      <div className="memory-board" style={style} role="group" aria-label={`${size} by ${size} cards`}>
        {game.board.deck.map((faceId, position) => (
          <Card
            key={position}
            position={position}
            columns={size}
            faceId={faceId}
            visible={revealed.has(position)}
            matched={matched.has(position)}
            blocked={blocked}
            tabIndex={position === tabStop ? 0 : -1}
            onActivate={onActivate}
            onFocus={rememberFocus}
            onRef={(node) => {
              if (node === null) cards.current.delete(position);
              else cards.current.set(position, node);
            }}
          />
        ))}
      </div>
    </div>
  );
}

export const Board = forwardRef<BoardHandle, BoardProps>(function Board(props, ref) {
  return <BoardContent {...props} expose={ref} />;
});
import type { FocusEventHandler, MouseEventHandler } from 'react';
import { Face } from './Face.tsx';
import { describeFace } from './faces.ts';

export type CardProps = Readonly<{
  position: number;
  columns: number;
  faceId: number;
  visible: boolean;
  matched: boolean;
  blocked: boolean;
  tabIndex: 0 | -1;
  onActivate: (position: number) => void;
  onFocus: FocusEventHandler<HTMLButtonElement>;
  onRef: (node: HTMLButtonElement | null) => void;
}>;

export function Card({ position, columns, faceId, visible, matched, blocked, tabIndex, onActivate, onFocus, onRef }: CardProps): React.JSX.Element {
  const row = Math.floor(position / columns) + 1;
  const column = (position % columns) + 1;
  const state = matched ? 'matched' : visible ? 'revealed' : 'closed';
  const name = matched || visible
    ? `Row ${row}, column ${column}, ${faceName(faceId)}, ${state}`
    : `Row ${row}, column ${column}, closed`;

  const activate: MouseEventHandler<HTMLButtonElement> = (event) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    onActivate(position);
  };
  const classes = ['memory-card', visible || matched ? 'memory-card--face' : 'memory-card--back'];
  if (matched) classes.push('memory-card--matched');

  return (
    <button
      ref={onRef}
      className={classes.join(' ')}
      type="button"
      data-position={position}
      aria-label={name}
      aria-disabled={matched || blocked}
      tabIndex={tabIndex}
      onClick={activate}
      onFocus={onFocus}
      style={{ scrollMargin: '6px' }}
    >
      {visible || matched ? <Face id={faceId} /> : <Back />}
      {matched && <span className="card-check" aria-hidden="true">✓</span>}
    </button>
  );
}

function faceName(id: number): string {
  return describeFace(id).name;
}

function Back(): React.JSX.Element {
  return (
    <svg className="card-back" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      <polygon points="50,27 73,50 50,73 27,50" fill="none" stroke="#757C9A" strokeWidth="4" />
    </svg>
  );
}
.board-scroll {
  max-height: min(70dvh, 768px);
  overflow: auto;
  padding: 6px;
  border: 1px solid #757C9A;
  border-radius: 14px;
  background: #141827;
  overscroll-behavior: contain;
}

.memory-board {
  display: grid;
  width: max-content;
  grid-template-columns: repeat(var(--column-count), var(--card-edge));
  gap: 6px;
}

.memory-card {
  position: relative;
  display: grid;
  width: var(--card-edge);
  height: var(--card-edge);
  padding: 0;
  place-items: center;
  border: 2px solid #757C9A;
  border-radius: 8px;
  color: #F4F6FF;
  cursor: pointer;
  transition: border-color 120ms ease;
  flex: none;
}

.memory-card--back { background: #1B2034; }
.memory-card--face { background: #111625; }
.memory-card:hover { border-color: #F4F6FF; }
.memory-card--matched,
.memory-card--matched:hover { border-color: #8BEA7D; }
.memory-card[aria-disabled="true"] { cursor: default; }

.memory-card:focus-visible {
  outline: 3px solid #FFF;
  outline-offset: 2px;
  z-index: 1;
}

.card-face,
.card-back { display: block; width: 100%; height: 100%; }
.card-check { position: absolute; right: 2px; bottom: 0; color: #8BEA7D; font-size: 14px; line-height: 14px; }

@media (prefers-reduced-motion: reduce) {
  .memory-card { transition: none; }
}

