import { useCallback, useEffect, useRef, useState } from 'react';
import { BOARD_SIZES, MAX_BOARD_SEED, type BoardSize } from '../constants.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { activateCard, advanceGame, createGame, isWon } from '../transitions.ts';
import type { GameState } from '../types.ts';
import { formatElapsedTime } from './formatTime.ts';
import { readPreferences, writePreferences, type SessionPreferences } from './storage.ts';

export type SessionAnnouncement = Readonly<{ id: number; text: string }>;
export type GameSession = Readonly<{
  state: GameState;
  paused: boolean;
  revision: number;
  best: number | null;
  celebration: boolean;
  announcement: SessionAnnouncement | null;
  loadStatus: string;
  activateCard: (index: number) => void;
  newGame: () => void;
  restart: () => void;
  changeSize: (size: number) => void;
  loadBoard: (draft: string) => boolean;
  loadSnapshot: (draft: string) => boolean;
  exportSnapshot: () => string;
  resume: () => void;
}>;

function isBoardSize(value: number): value is BoardSize {
  return BOARD_SIZES.some((size) => size === value);
}

function freshBoardCode(size: BoardSize, currentCode?: string): string {
  let seed: number;
  try {
    const values = new Uint32Array(1);
    window.crypto.getRandomValues(values);
    seed = ((values[0] ?? 0) % MAX_BOARD_SEED) + 1;
  } catch {
    seed = (Date.now() % MAX_BOARD_SEED) + 1;
  }
  let code = `np1-${size}-${seed}`;
  if (code === currentCode) {
    seed = seed === MAX_BOARD_SEED ? 1 : seed + 1;
    code = `np1-${size}-${seed}`;
  }
  return code;
}

function initialGame(size: BoardSize): GameState {
  const game = createGame(freshBoardCode(size));
  if (game === null) throw new Error('Could not create an initial game.');
  return game;
}

function announcementForTurn(previous: GameState, next: GameState): string {
  if (next.matched.length > previous.matched.length) {
    if (isWon(next)) {
      return `Pair found. All pairs found in ${next.moves} moves and ${formatElapsedTime(next.elapsedMs)}.`;
    }
    const pairs = next.matched.length / 2;
    return `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`;
  }
  return 'No match. Cards close after a short pause.';
}

export function useGameSession(): GameSession {
  const [preferences, setPreferences] = useState<SessionPreferences>(readPreferences);
  const [state, setState] = useState<GameState>(() => initialGame(preferences.size));
  const [paused, setPaused] = useState(false);
  const [revision, setRevision] = useState(0);
  const [celebration, setCelebration] = useState(false);
  const [announcement, setAnnouncement] = useState<SessionAnnouncement | null>(null);
  const [loadStatus, setLoadStatus] = useState('');
  const [pageVisible, setPageVisible] = useState(() =>
    typeof document === 'undefined' || document.visibilityState !== 'hidden',
  );
  const gameRef = useRef(state);
  const preferencesRef = useRef(preferences);
  const pausedRef = useRef(paused);
  const visibleRef = useRef(pageVisible);
  const activeAtRef = useRef<number | null>(null);
  const generationRef = useRef(0);
  const announcementIdRef = useRef(0);
  const flushRef = useRef<(now: number) => void>(() => undefined);

  preferencesRef.current = preferences;
  pausedRef.current = paused;
  visibleRef.current = pageVisible;

  const flushAt = (now: number): void => {
    const current = gameRef.current;
    if (!visibleRef.current || pausedRef.current || !current.started || isWon(current)) {
      activeAtRef.current = null;
      return;
    }
    const previousTime = activeAtRef.current;
    activeAtRef.current = now;
    if (previousTime === null) return;
    const advanced = advanceGame(current, now - previousTime);
    if (advanced !== current) {
      gameRef.current = advanced;
      setState(advanced);
    }
  };
  flushRef.current = flushAt;

  const notify = useCallback((text: string): void => {
    announcementIdRef.current += 1;
    setAnnouncement({ id: announcementIdRef.current, text });
  }, []);

  const persist = useCallback((next: SessionPreferences): void => {
    preferencesRef.current = next;
    setPreferences(next);
    writePreferences(next);
  }, []);

  const setPause = useCallback((next: boolean): void => {
    pausedRef.current = next;
    setPaused(next);
  }, []);

  const replaceGame = useCallback((next: GameState, pauseForResume: boolean): void => {
    generationRef.current += 1;
    activeAtRef.current = null;
    gameRef.current = next;
    setState(next);
    setPause(pauseForResume);
    setRevision((current) => current + 1);
    setCelebration(false);
  }, [setPause]);

  const reportLoad = useCallback((status: string): void => {
    setLoadStatus(status);
    notify(status);
  }, [notify]);

  const activate = useCallback((index: number): void => {
    const now = performance.now();
    flushRef.current(now);
    const previous = gameRef.current;
    if (pausedRef.current) return;
    const next = activateCard(previous, index);
    if (next === previous) return;
    if (!previous.started && next.started) activeAtRef.current = now;
    gameRef.current = next;
    setState(next);
    if (previous.selection.kind !== 'closed' && previous.selection.kind !== 'mismatch') {
      notify(announcementForTurn(previous, next));
      if (isWon(next)) {
        setCelebration(true);
        const currentBest = preferencesRef.current.bestScores[next.board.size];
        if (currentBest === undefined || next.moves < currentBest) {
          const bestScores = { ...preferencesRef.current.bestScores, [next.board.size]: next.moves };
          persist({ ...preferencesRef.current, bestScores });
        }
      }
    }
  }, [notify, persist]);

  const replaceWithFreshGame = useCallback((size: BoardSize, currentCode?: string): void => {
    const next = createGame(freshBoardCode(size, currentCode));
    if (next === null) return;
    replaceGame(next, false);
  }, [replaceGame]);

  const newGame = useCallback((): void => {
    const current = gameRef.current;
    replaceWithFreshGame(current.board.size, current.board.code);
  }, [replaceWithFreshGame]);

  const restart = useCallback((): void => {
    const next = createGame(gameRef.current.board.code);
    if (next !== null) replaceGame(next, false);
  }, [replaceGame]);

  const changeSize = useCallback((size: number): void => {
    if (!isBoardSize(size) || size === gameRef.current.board.size) return;
    replaceWithFreshGame(size);
    persist({ ...preferencesRef.current, size });
  }, [persist, replaceWithFreshGame]);

  const saveLoadedSize = useCallback((size: BoardSize): void => {
    persist({ ...preferencesRef.current, size });
  }, [persist]);

  const loadBoard = useCallback((draft: string): boolean => {
    const next = createGame(draft.trim());
    if (next === null) {
      reportLoad('Invalid board code.');
      return false;
    }
    replaceGame(next, false);
    saveLoadedSize(next.board.size);
    reportLoad('Board loaded.');
    return true;
  }, [reportLoad, replaceGame, saveLoadedSize]);

  const loadSnapshot = useCallback((draft: string): boolean => {
    const next = decodeSnapshot(draft);
    if (next === null) {
      reportLoad('Invalid snapshot.');
      return false;
    }
    const completed = isWon(next);
    replaceGame(next, !completed);
    saveLoadedSize(next.board.size);
    reportLoad(completed ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
    return true;
  }, [reportLoad, replaceGame, saveLoadedSize]);

  const exportSnapshot = useCallback((): string => {
    flushRef.current(performance.now());
    return encodeSnapshot(gameRef.current);
  }, []);

  const resume = useCallback((): void => {
    activeAtRef.current = performance.now();
    setPause(false);
  }, [setPause]);

  const clockRunning = state.started && !isWon(state) && !paused && pageVisible;
  useEffect(() => {
    if (!clockRunning) {
      activeAtRef.current = null;
      return;
    }
    if (activeAtRef.current === null) activeAtRef.current = performance.now();
    const generation = generationRef.current;
    const interval = window.setInterval(() => {
      if (generation === generationRef.current) flushRef.current(performance.now());
    }, 50);
    return () => window.clearInterval(interval);
  }, [clockRunning, revision]);

  useEffect(() => {
    const onVisibilityChange = (): void => {
      const now = performance.now();
      flushRef.current(now);
      const visible = document.visibilityState !== 'hidden';
      visibleRef.current = visible;
      setPageVisible(visible);
      activeAtRef.current = visible && !pausedRef.current ? now : null;
    };
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => document.removeEventListener('visibilitychange', onVisibilityChange);
  }, []);

  useEffect(() => () => {
    generationRef.current += 1;
  }, []);

  return {
    state,
    paused,
    revision,
    best: preferences.bestScores[state.board.size] ?? null,
    celebration,
    announcement,
    loadStatus,
    activateCard: activate,
    newGame,
    restart,
    changeSize,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    resume,
  };
}

