import assert from 'node:assert/strict';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { chromium } from '@playwright/test';
const browser = await chromium.launch({ headless: true });
try {
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  const remoteRequests = [];
  page.on('request', request => { if (!request.url().startsWith('file:')) remoteRequests.push(request.url()); });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto(pathToFileURL(resolve('dist/index.html')).href);
  await page.getByRole('heading', { name: 'Neon Pairs' }).waitFor();
  assert.equal(await page.getByRole('combobox', { name: 'Grid size' }).inputValue(), '4');
  const details = page.locator('details');
  await details.locator('summary').click();
  await page.getByLabel('Board code').fill('np1-4-1');
  await page.getByRole('button', { name: 'Load board' }).click();
  const first = page.getByRole('button', { name: 'Row 1, column 1, closed' });
  const second = page.getByRole('button', { name: 'Row 1, column 2, closed' });
  assert.equal(await first.getAttribute('data-position'), '0');
  await first.click();
  assert.equal(await page.locator('.game-summary').innerText(), 'Moves: 0\nPairs: 0/8\nTime: 0:00\nBest: none');
  assert.match(await page.getByRole('button', { name: /Row 1, column 1, cyan solid plus, marker top, revealed/ }).getAttribute('class'), /memory-card--face/);
  await second.click();
  assert.equal(await page.locator('.game-summary').locator('p').first().innerText(), 'Moves: 1');
  assert.equal(await first.getAttribute('aria-disabled'), 'true');
  assert.equal(await page.locator('[role=status]').getAttribute('aria-live'), 'polite');
  assert.equal((await page.locator('.memory-card--back').count()), 14);
  assert.deepEqual(remoteRequests, []);
  assert.deepEqual(errors, []);
  await context.close();
  process.stdout.write('Offline Chromium smoke passed: load, reveal, mismatch, status and no network requests.\n');
} finally {
  await browser.close();
}
EOF","workdir":"/work","yield_time_ms":30000,"max_output_tokens":5000}));

