    if (area === null) return;
    const updateSize = (): void => {
      const innerWidth = Math.max(0, area.clientWidth - 12);
      const gaps = (size - 1) * 6;
      const edge = Math.max(44, Math.min(88, (innerWidth - gaps) / size));
      setCardEdge((current) => current === edge ? current : edge);
